const extractionLabels={json:'JSON 响应正文',header:'响应头',sse:'SSE 匹配事件'}
const evidenceInput=ref(null),evidenceTitle=ref(''),evidenceState=ref({dirty:false,busy:false})
function linkBug(){evidenceInput.value={kind:'test',service:result.value.service,run_id:result.value.id};evidenceTitle.value=result.value.name||'接口测试未通过'}
async function retryRegression(){try{await bugAPI('bug-evidence/link',{kind:'test',service:result.value.service,run_id:result.value.id,work_item_id:result.value.bug_id,request_key:'regression-run-'+result.value.id});result.value.bug_evidence_error='';toast('回归结果已关联','success')}catch(e){toast(e.message,'error')}}
const props=defineProps({recordsOnly:Boolean,recordService:String,embeddedHistory:Boolean})
const emit=defineEmits(['back','service-change','history-state'])
const executionMode=ref('manual'),suites=ref([]),suiteID=ref(null),historyRefresh=ref(0),unitFilter=ref(null)
const selectedSuite=computed(()=>suites.value.find(s=>s.id===suiteID.value)),executionPlan=computed(()=>suitePlan(selectedSuite.value,cases.value))
const visibleSteps=computed(()=>(result.value?.steps||[]).map((step,index)=>({step,index})).filter(({index})=>unitFilter.value==null||!result.value?.units?.length||(index>=result.value.units[unitFilter.value]?.start&&index<result.value.units[unitFilter.value]?.end)))
const route=useRoute(),router=useRouter(),services=ref([]),service=ref(''),environment=ref(''),target=ref(''),context=ref({environments:[],targets:[],variables:[]}),me=ref(null)
const scenario=ref(route.query.scope==='scenario'),scenarioSelection=ref({}),uncertainScenario=ref(false)
const historyView=ref(false)
const reportCanvas=ref(false)
const reportFlowUnit=computed(()=>result.value?.units?.[unitFilter.value??0])
const reportFlowSteps=computed(()=>{const u=reportFlowUnit.value;return u?(result.value?.steps||[]).slice(u.start,u.end):result.value?.steps||[]})
const reviewCase=computed(()=>reportCaseLink(result.value,unitFilter.value))
const openSteps=ref([]),stepPanels=[],summary=computed(()=>result.value?runSummary(result.value):null)
const editor=ref(requestDraft(emptyRequest())),requestEditor=ref(null),request=computed(()=>editor.value.request),name=ref('未命名测试'),cases=ref([]),caseID=ref(null),caseRevision=ref(0),documentID=ref(0),result=ref(null),selectedTab=ref(initialConsoleTab(route.query,props.recordsOnly))
if(route.query.case){executionMode.value='case';caseID.value=Number(route.query.case)}
if(route.query.suite){executionMode.value='suite';suiteID.value=Number(route.query.suite)}
const contextError=ref(''),saveOpen=ref(false),saveName=ref(''),saveNameError=ref(''),saveNameInput=ref(null),reportReturn=ref('request')
const historyPage=computed(()=>!historyView.value&&isHistoryTab(selectedTab.value)),editorPage=computed(()=>!historyPage.value&&!historyView.value&&!props.recordsOnly)
const pageTitle=computed(()=>historyView.value?'测试报告':historyPage.value?(selectedTab.value==='caseHistory'?'用例执行记录':'调试历史'):executionMode.value==='case'?'执行用例':executionMode.value==='suite'?'执行测试集':'接口调试')
const blocker=computed(()=>scenario.value?(scenarioBlocker({loading:loading.value,error:contextError.value,context:context.value,environment:environment.value,caseID:caseID.value,selection:scenarioSelection.value,admin:admin.value})?{message:scenarioBlocker({loading:loading.value,error:contextError.value,context:context.value,environment:environment.value,caseID:caseID.value,selection:scenarioSelection.value,admin:admin.value}),action:'refresh'}:null):contextBlocker({service:service.value,loading:loading.value,error:contextError.value,context:context.value,environment:environment.value,target:target.value,admin:admin.value}))
const runBlocker=computed(()=>(scenario.value&&uncertainScenario.value?'上次提交结果待核对，请先查看执行记录':blocker.value?.message)||(executionMode.value==='case'&&!selectedCase.value?'用例不存在或无权访问':executionMode.value==='suite'&&(!selectedSuite.value||executionPlan.value.missing)?'测试集包含不可访问的用例，请返回测试集核对':executionMode.value==='suite'&&(executionPlan.value.units>20||executionPlan.value.steps>100)?'测试集超出 20 个组合或 100 步，请拆分后执行':''))
const pendingRunID=ref(0),pollError=ref(false)
const loading=ref(false),saving=ref(false),starting=ref(false),profileOpen=ref(false),profileSaving=ref(false),profile=ref({revision:0,enabled:true,base_url:'',auth:{mode:'none',path:'/login',body:'{}',token_pointer:'/data/token',header:'Authorization',prefix:'Bearer ',token_variable:''}})
const protectedOpen=ref(false),reason=ref(''),pendingInput=ref(null),baseline=ref('')
const selectedCase=computed(()=>scenario.value?(context.value.case?.id===caseID.value?context.value.case:null):cases.value.find(c=>c.id===caseID.value))
const admin=computed(()=>me.value?.role==='admin'),active=computed(()=>running(result.value?.status)),busy=computed(()=>starting.value||active.value),currentEnv=computed(()=>context.value.environments.find(v=>v.name===environment.value))
const targetChoices=computed(()=>context.value.targets.filter(t=>executionMode.value!=='manual'||(t.protocol==='dubbo')===(editor.value.request.mode==='dubbo')))
watch(()=>[editor.value.request.mode,context.value.targets],()=>{if(!targetChoices.value.some(t=>t.key===target.value))target.value=targetChoices.value[0]?.key||''})
const targetInfo=computed(()=>context.value.targets.find(v=>v.key===target.value))
const fingerprint=()=>JSON.stringify(editor.value)
const dirty=computed(()=>baseline.value!==''&&baseline.value!==fingerprint())
let pollTimer=null,epoch=0,runEpoch=0,destroyed=false,initialized=false,routeWrites=0,lastSeed='',routeSequence=0
async function api(path,options){if(scenario.value)path=path.replace(/^cases(?=[/?]|$)/,'scenario-cases').replace(/^runs(?=[/?]|$)/,'scenario-runs');const r=await fetch('api/api-testing/'+path,options);const body=await r.json().catch(()=>({}));if(!r.ok||body.error)throw Error(body.error||'请求失败');return body}
const scope=()=>'?service='+encodeURIComponent(service.value),envScope=()=>scope()+'&environment='+encodeURIComponent(environment.value)
const json=(method,body)=>({method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
function markClean(){baseline.value=fingerprint()}
async function leaveDraft(){if(props.embeddedHistory)return await canCloseHistory();if(busy.value)return false;return !dirty.value||await confirmAction('切换后当前未保存的测试草稿会丢失。','切换测试')}
function contextMessage(){if(props.embeddedHistory)return;const label=pageTitle.value;const query={...route.query};if(scenario.value)query.scope='scenario';else delete query.scope;delete query.case;delete query.suite;if(executionMode.value==='suite'&&suiteID.value)query.suite=suiteID.value;if(!historyView.value&&!(scenario.value&&result.value?.id))delete query.run;if(scenario.value&&result.value?.id)query.run=String(result.value.id);if(historyPage.value){query.view='history';query.source=selectedTab.value==='caseHistory'?'case':'manual'}else{delete query.view;delete query.source;}if(executionMode.value==='case'&&caseID.value)query.case=caseID.value;routeWrites++;router.replace({path:props.recordsOnly?'/test-cases':'/test-execution',query:{...query,service:service.value,...(props.recordsOnly?{tab:'records'}:{}),...(environment.value?{environment:environment.value}:{})}}).finally(()=>routeWrites--);document.title=label+(service.value?' · '+service.value:'');if(window.parent!==window){window.parent.postMessage({type:'context.update',service:service.value,environment:environment.value},location.origin);window.parent.postMessage({type:'workspace.label',label:document.title},location.origin)}}
async function loadScenarioContext(preferred){
 const token=++epoch,id=caseID.value;loading.value=true;contextError.value='';scenarioSelection.value={}
 try{
  if(!id){context.value={environments:[],targets:[],variables:[],applications:[]};environment.value='';return}
  let data=await api('cases/'+id+'/context'),chosen=data.environments.some(e=>e.name===preferred)?preferred:(data.environments.find(e=>!e.protected)||data.environments[0])?.name||''
  if(chosen)data=await api('cases/'+id+'/context?environment='+encodeURIComponent(chosen))
  if(token!==epoch||caseID.value!==id||!scenario.value)return
  context.value={targets:[],variables:[],...data};environment.value=chosen
  cases.value=[...cases.value.filter(c=>c.id!==id),data.case];caseRevision.value=data.case.revision
  scenarioSelection.value=Object.fromEntries((data.applications||[]).map(app=>[app.service,app.targets?.length===1?app.targets[0].key:'']))
  contextMessage()
 }catch(e){if(token===epoch){contextError.value=e.message;context.value={environments:[],targets:[],variables:[],applications:[]};toast(e.message,'error')}}finally{if(token===epoch)loading.value=false}
}
async function loadContext(preferred){if(scenario.value)return loadScenarioContext(preferred);const token=++epoch,app=service.value,query='?service='+encodeURIComponent(app);loading.value=true;contextError.value='';try{let data=await api('context'+query+(preferred?'&environment='+encodeURIComponent(preferred):''));const chosen=data.environments.some(e=>e.name===preferred)?preferred:(data.environments.find(e=>!e.protected)||data.environments[0])?.name||'';if(chosen&&chosen!==preferred)data=await api('context'+query+'&environment='+encodeURIComponent(chosen));if(token!==epoch||service.value!==app)return;context.value=data;environment.value=chosen;target.value=route.query.bug?(data.targets.find(t=>t.key===route.query.target&&chosen===route.query.environment)?.key||(data.targets.length===1?data.targets[0].key:'')):(data.targets[0]?.key||'');contextMessage()}catch(e){if(token===epoch){contextError.value=e.message;context.value={environments:[],targets:[],variables:[],enabled:false};target.value='';toast(e.message,'error')}}finally{if(token===epoch)loading.value=false}}

async function loadCollections(){if(scenario.value){const data=await api('cases');if(!scenario.value)return;cases.value=data.cases;suites.value=[];historyRefresh.value++;if(caseID.value&&!busy.value)await loadScenarioContext(environment.value);return}const app=service.value,q=scope();const [c,sets]=await Promise.all([api('cases'+q),api('suites'+q)]);if(service.value===app){cases.value=c;suites.value=sets;historyRefresh.value++}}
function clearRequestLink(){if(props.embeddedHistory)return;const query={...route.query,service:service.value};for(const key of ['case','suite','snapshot','operation','run'])delete query[key];lastSeed=[service.value,undefined,undefined].join('|');routeWrites++;router.replace({query}).finally(()=>routeWrites--)}
async function changeService(value,confirmed=false){const previousTab=selectedTab.value;if(!confirmed&&!await leaveDraft())return;stopPolling();if(props.embeddedHistory){evidenceInput.value=null;evidenceState.value={dirty:false,busy:false}}epoch++;service.value=value||'';scenario.value=!value;if(scenario.value){executionMode.value='case';selectedTab.value=props.recordsOnly?'caseHistory':'request'}if(props.recordsOnly)emit('service-change',value);historyView.value=false;result.value=null;caseID.value=null;suiteID.value=null;documentID.value=0;executionMode.value=scenario.value?'case':'manual';editor.value=requestDraft(emptyRequest());name.value='未命名测试';selectedTab.value=props.recordsOnly?'caseHistory':isHistoryTab(previousTab)?(scenario.value?'caseHistory':previousTab):'request';markClean();if(!confirmed)clearRequestLink();await loadContext();await loadCollections()}
async function changeEnvironment(value){if(busy.value)return;environment.value=value;historyView.value=false;result.value=null;await loadContext(value)}
async function selectCase(id){if(busy.value)return;const c=cases.value.find(v=>v.id===id);if(!c)return;caseID.value=c.id;caseRevision.value=c.revision;result.value=null;if(scenario.value)await loadScenarioContext(environment.value);else contextMessage()}
async function selectSuite(id){if(busy.value)return;suiteID.value=id;result.value=null;contextMessage()}
async function newCase(){if(!await leaveDraft())return;caseID.value=null;caseRevision.value=0;documentID.value=0;name.value='未命名测试';editor.value=requestDraft(emptyRequest());result.value=null;markClean();clearRequestLink()}
function openSaveCase(){if(busy.value)return;try{const request=composeEditorRequest(editor.value);saveName.value=name.value==='未命名测试'?requestName(request):name.value;saveNameError.value='';saveOpen.value=true;nextTick(()=>focusControl(saveNameInput.value))}catch(e){focusControl(requestEditor.value,e.field);toast(e.message,'warning')}}
async function saveCase(){if(saving.value||busy.value)return false;if(!saveName.value.trim()){saveNameError.value='请填写用例名称';focusControl(saveNameInput.value);return false}saving.value=true;try{const req=composeEditorRequest(editor.value);await api('cases'+scope(),json('POST',{id:0,name:saveName.value.trim(),revision:0,document_id:documentID.value,operation_id:route.query.operation||'',request:req}));await loadCollections();name.value=saveName.value.trim();markClean();saveOpen.value=false;toast('已保存为用例，可在测试用例中完善步骤','success')}catch(e){focusControl(requestEditor.value,e.field);toast(e.message,'error')}finally{saving.value=false}return false}
function openWorkspace(hash,plugin='api-center'){if(window.parent!==window)window.parent.postMessage({type:'workspace.open',plugin,hash},location.origin);else window.open((plugin==='api-center'?location.pathname:'/api/plugins/'+plugin+'/ui')+hash,'_blank','noopener')}
function openCaseList(){openWorkspace('#/test-cases?'+new URLSearchParams({... (scenario.value?{scope:'scenario'}:{service:service.value}),...(executionMode.value==='suite'?{tab:'suites'}:{})}))}
function configureEnvironment(){openWorkspace('#/svc/'+encodeURIComponent(service.value)+'/environment','deploy')}
function resolveBlocker(){if(blocker.value?.action==='environment')configureEnvironment();else if(blocker.value?.action==='refresh')loadContext(environment.value);else if(admin.value)openProfile()}
function chooseView(tab){if(busy.value||historyView.value)return;selectedTab.value=tab;contextMessage()}


function openDelivery(){const hash='#/orchestration?run='+result.value.delivery_run_id;if(window.parent!==window)window.parent.postMessage({type:'workspace.open',plugin:'deploy',hash},location.origin);else window.open('/api/plugins/deploy/ui'+hash,'_blank','noopener')}
function stopPolling(){clearTimeout(pollTimer);pollTimer=null;runEpoch++}
async function readRun(id){pendingRunID.value=id;pollError.value=false;const currentService=service.value,token=runEpoch;try{const data=await api('runs/'+id+scope());if(destroyed||currentService!==service.value||token!==runEpoch)return;const oldID=result.value?.id,oldStatus=result.value?.status;result.value=data;if(oldID!==data.id)unitFilter.value=null;if(oldID!==data.id||(oldStatus!==data.status&&!running(data.status))){const i=runSummary(data).firstFailure;openSteps.value=i>=0?[i]:[]}if(running(data.status))pollTimer=setTimeout(()=>readRun(id),600);else{starting.value=false;await loadCollections()}}catch(e){if(destroyed||currentService!==service.value||token!==runEpoch)return;pollError.value=true;toast(e.message+'；不会重新发送测试请求，可从测试记录继续核对。','error');starting.value=false}}
async function send(){if(busy.value)return;
 if(scenario.value){if(runBlocker.value){toast(runBlocker.value,'warning');return}const input={request_id:randomUUID(),environment:environment.value,case_id:caseID.value,case_revision:context.value.case.revision,targets:scenarioTargets(context.value,scenarioSelection.value)};if(context.value.protected){pendingInput.value=input;reason.value='';protectedOpen.value=true;return}await execute(input);return}
 if(runBlocker.value){toast(runBlocker.value,'warning');return;}try{const c=executionMode.value==='case'?selectedCase.value:null,group=executionMode.value==='suite'?selectedSuite.value:null;if(executionMode.value==='case'&&!c)throw Error('请选择已保存用例');if(executionMode.value==='suite'&&(!group||executionPlan.value.missing||executionPlan.value.units>20||executionPlan.value.steps>100))throw Error('请刷新测试集并核对有效用例；单次最多 20 个数据组合、100 步');const input={bug_id:Number(route.query.bug)||0,request_id:randomUUID(),name:group?.name||c?.name||requestName(editor.value.request),environment:environment.value,target_key:target.value,target_fingerprint:targetInfo.value.fingerprint,document_id:c?.document_id||documentID.value,case_id:c?.id||0,case_revision:c?.revision||0,suite_id:group?.id||0,suite_revision:group?.revision||0,case_revisions:group?executionPlan.value.revisions:undefined,request:c||group?undefined:composeEditorRequest(editor.value)};if(currentEnv.value?.protected){pendingInput.value=input;reason.value='';protectedOpen.value=true;return}await execute(input)}catch(e){focusControl(requestEditor.value,e.field);toast(e.message,'error')}}
function syncReportRoute(id){if(props.embeddedHistory)return;const query={...route.query};if(id)query.run=String(id);else delete query.run;routeWrites++;router.replace({query}).finally(()=>routeWrites--)}
async function execute(input){historyView.value=false;starting.value=true;stopPolling();try{const v=await api('runs'+scope(),json('POST',input));result.value=v;syncReportRoute(v.id);selectedTab.value=props.recordsOnly?'report':'request';protectedOpen.value=false;pendingInput.value=null;starting.value=false;await loadCollections();await readRun(v.id)}catch(e){starting.value=false;if(scenario.value)uncertainScenario.value=true;toast(e.message+'；若提交结果不确定，请先查看测试记录，勿重复发送。','error')}}
async function confirmProtected(){if(!reason.value.trim()||!pendingInput.value)return;await execute({...pendingInput.value,confirm_protected:true,reason:reason.value})}
async function stop(){if(!result.value)return;stopPolling();try{await api('runs/'+result.value.id+'/stop'+scope(),{method:'POST'});toast('已请求停止执行；已到达业务接口的操作不会被回滚','info');await readRun(result.value.id)}catch(e){toast(e.message,'error')}}
async function showRun(record){if(busy.value&&record.id!==result.value?.id)return;const from=selectedTab.value;stopPolling();result.value=null;historyView.value=true;await readRun(record.id);reportReturn.value=reportReturnTab(from,result.value,props.recordsOnly);if(result.value?.id===record.id)syncReportRoute(record.id)}
function returnToEditor(){if(active.value)return;stopPolling();historyView.value=false;result.value=null;selectedTab.value=reportReturn.value;syncReportRoute(null);contextMessage()}

const profileEditor=ref(null)
async function openProfile(){if(!environment.value)return;try{profile.value=await api('profile'+envScope());profile.value.auth={path:'/login',body:'{}',token_pointer:'/data/token',header:'Authorization',prefix:'Bearer ',token_variable:'',...profile.value.auth};profileOpen.value=true}catch(e){toast(e.message,'error')}}
async function saveProfile(){if(profileSaving.value)return;profileSaving.value=true;try{if(!profileEditor.value?.flush())return;await api('profile'+envScope(),json('PUT',profile.value));profileOpen.value=false;await loadContext(environment.value);toast('连接与认证已保存，该应用环境下的测试共用','success')}catch(e){toast(e.message,'error')}finally{profileSaving.value=false}}
function exportReport(){if(!result.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify(result.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='api-test-'+result.value.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function copyTrace(){return copyText(result.value.result.trace_id,{successMessage:'请求标识已复制',failureMessage:'请手动复制请求标识'})}
function stepLogs(step){const run={...result.value,service:step.service||result.value.service,environment:step.environment||result.value.environment,result:step.result},hash=logTarget(run);if(window.parent!==window){const q=new URL(hash.slice(1),'https://workspace.invalid').searchParams;window.parent.postMessage({type:'workspace.open',plugin:'logs',hash,context:{service:run.service,environment:run.environment,range:[Number(q.get('from')),Number(q.get('to'))]}},location.origin)}else window.open('/api/plugins/logs/ui'+hash,'_blank','noopener')}
function openLogs(){const hash=logTarget(result.value);if(window.parent!==window){const q=new URL(hash.slice(1),'https://workspace.invalid').searchParams;window.parent.postMessage({type:'workspace.open',plugin:'logs',hash,context:{service:result.value.service,environment:result.value.environment,range:[Number(q.get('from')),Number(q.get('to'))]}},location.origin)}else window.open('/api/plugins/logs/ui'+hash,'_blank','noopener')}
function openTrace(){if(window.parent!==window){window.parent.postMessage({type:'workspace.open',plugin:'monitor',hash:'#/trace?trace='+encodeURIComponent(result.value.result.trace_id),context:{service:result.value.service,environment:result.value.environment}},location.origin)}else window.open('/api/plugins/monitor/ui#/trace?trace='+encodeURIComponent(result.value.result.trace_id),'_blank','noopener')}
watch([dirty,busy,profileOpen,profileSaving,saveOpen,evidenceState],()=>{if(props.embeddedHistory){emit('history-state',{dirty:evidenceState.value.dirty,busy:evidenceState.value.busy});return}if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',dirty:dirty.value||profileOpen.value||saveOpen.value||evidenceState.value.dirty,busy:busy.value||profileSaving.value||evidenceState.value.busy},location.origin)})
watch(pageTitle,()=>{if(initialized)contextMessage()})
