 if(!initialized||routeWrites||props.recordsOnly)return
 const q={...route.query};if((q.scope==='scenario')!==scenario.value){if(!await leaveDraft()){contextMessage();return}scenario.value=q.scope==='scenario';service.value=scenario.value?'':String(q.service||'');caseID.value=q.case?Number(q.case):null;executionMode.value=scenario.value||q.case?'case':'manual';result.value=null;historyView.value=false;selectedTab.value=initialConsoleTab(q);await loadCollections();await loadContext(q.environment);if(q.run)await showRun({id:Number(q.run)});return}
 const sequence=++routeSequence,app=q.service||service.value,seed=[app,q.snapshot,q.operation].join('|')
