ength"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div><SSEViewer v-if="step.request.mode==='sse'" :events="step.result.events||[]" :active="active&&step.status==='running'" :can-assert="!active&&!!result.case_id&&!(result.units?.length>1)" :can-extract="!active&&!!result.case_id&&!(result.units?.length>1)" @assert="field=>editReportField(field,i,'assertion')" @extract="field=>editReportField(field,i,'extraction')"/><ResponseViewer v-else :body="step.result.body||''" :truncated="step.result.truncated" :can-assert="!active&&!!result.case_id&&!(result.units?.length>1)" :can-extract="!active&&!!result.case_id&&!(result.units?.length>1)" @assert="field=>editReportField(field,i,'assertion')" @extract="field=>editReportField(field,i,'extraction')"/><AssertionResults :checks="step.result.checks||[]"/></AccordionContent></AccordionItem></Accordion><dl class="grid min-w-0 gap-4 sm:grid-cols-2"><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">执行环境</dt><dd class="min-w-0 break-words">{{result.environment}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">{{rpcResult?'RPC 结果':(result.steps?.length?'最近步骤 HTTP 状态':'HTTP 状态')}}</dt><dd class="min-w-0 break-words">{{rpcResult?(result.result.rpc_success===true?'调用成功':result.result.exception_type?'业务异常':active?'等待结果':result.result.unknown?'结果未知':'未完成'):result.result.status||(active?'等待响应':['authentication','validation'].includes(result.result.phase)?'业务请求未发送':'未收到响应')}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">{{active?(rpcResult?'调用耗时':'首包耗时'):result.steps?.length?'最近步骤耗时':'总耗时'}}</dt><dd class="min-w-0 break-words">{{result.result.duration_ms||0}} ms</dd></div><div v-if="result.steps?.length" class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">{{result.units?.some(u=>u.case_snapshot?.graph)?'累计请求耗时':result.suite_id?'测试集总耗时':'用例总耗