<style scoped>.api-testing{flex:1;width:100%;min-width:0;height:100dvh;overflow:auto;box-sizing:border-box;background:var(--bg);color:var(--text)}.execution-context{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:16px;margin-bottom:20px}.execution-context{flex-shrink:0}.target-form{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.7fr) minmax(0,1.4fr) auto;align-items:end;gap:16px;margin:0}.context-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;min-height:32px}.console-empty{min-height:240px;border:1px dashed var(--border)}.request-workspace,.result-section{min-width:0}.context-feedback{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:8px;color:var(--muted-foreground);font-size:.875rem}.execution-name{font-size:1.125rem;margin-right:auto;overflow-wrap:anywhere}.case-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:16px}.result-section{border-top:1px solid var(--border);margin-top:24px;padding-top:20px}.result-section.report-only{margin-top:8px;padding-top:8px;border-top:0}.result-heading{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-bottom:16px}.result-heading h3{margin:0;font-size:1.125rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:var(--mono);font-size:.75rem;background:var(--panel2);padding:12px;max-height:500px;overflow:auto}.error-text{color:var(--destructive);overflow-wrap:anywhere}.report-summary{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:16px 0}.history-actions{margin-bottom:16px}.unit-filter{margin-top:16px}.data-preview{margin-bottom:16px}.variable-list{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:16px}code{overflow-wrap:anywhere}@media(max-width:1024px){.target-form{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:640px){.target-form{grid-template-columns:minmax(0,1fr)}}</style>

